{
  "name": "@daoninc/opencode-file-explorer",
  "version": "0.1.1",
  "description": "Searchable read-only file explorer and preview panel for OpenCode",
  "type": "module",
  "license": "MIT",
  "exports": {
    "./tui": "./dist/tui.js",
    "./model": { "types": "./dist/model.d.ts", "default": "./dist/model.js" },
    "./prompt": { "types": "./dist/prompt.d.ts", "default": "./dist/prompt.js" },
    "./prompt-focus": { "types": "./dist/prompt-focus.d.ts", "default": "./dist/prompt-focus.js" }
  },
  "files": ["dist", "README.md", "LICENSE"],
  "scripts": { "test": "bun test", "prepack": "bun run ../../scripts/build.ts .", "prepublishOnly": "bun run ../../scripts/build.ts . && bun run ../../scripts/check-release.ts ." },
  "dependencies": { "@opencode/plugin": "^2.3.1" },
  "peerDependencies": { "@opentui/core": ">=0.8.4 <0.9", "@opentui/solid": ">=0.8.4 <0.9", "solid-js": "^1.9.0" },
  "publishConfig": { "access": "public", "registry": "https://registry.npmjs.org/" },
  "keywords": ["opencode", "opencode-plugin", "tui", "file-explorer"],
  "repository": { "type": "git", "url": "git+https://github.com/daon-private/sdk-tools.git", "directory": "AI/opencode/plugins/file-explorer" }
}
